SELECT a.account_id, a.name, a.status FROM accounts a
INNER JOIN account_roles ar ON ar.account_id = a.account_id INNER JOIN roles r ON r.role_id = ar.role_id AND r.code = #{roleCode}
AND a.name ILIKE '%' || #{name} || '%'
AND a.status IN
#{s}
ORDER BY a.account_id LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT a.account_id) FROM accounts a
INNER JOIN account_roles ar ON ar.account_id = a.account_id INNER JOIN roles r ON r.role_id = ar.role_id AND r.code = #{roleCode}
AND a.name ILIKE '%' || #{name} || '%'
AND a.status IN
#{s}

mapper.update:
UPDATE accounts
SET email        = #{row.email},
    name         = #{row.name},
    status       = #{row.status},
    suspended_at = #{row.suspendedAt},
    version      = #{row.version},
    updated_by   = #{row.updatedBy},
    updated_at   = #{row.updatedAt}
WHERE account_id = #{row.accountId}
  AND version    = #{prevVersion}
